-- Autopilot Ahmedabad Round 1, statement A2: create and fill every table in Supabase.
-- Paste into the Supabase SQL editor and run. Every value is text, exactly as in the pack:
-- dates and amounts come in mixed formats on purpose. Rerunning drops and recreates the tables.
-- Fully synthetic data, for this hackathon only.

drop table if exists public."approver_matrix";
create table public."approver_matrix" (
  row_id bigint generated always as identity primary key,
  "rule_id" text,
  "trigger" text,
  "value_band" text,
  "categories" text,
  "plant_code" text,
  "approver_role" text,
  "approver_name" text,
  "approver_email" text,
  "seniority_level" text
);
comment on table public."approver_matrix" is 'One rule saying who receives an escalation or a stopped invoice, by trigger, value band, category and plant.';

drop table if exists public."po_header";
create table public."po_header" (
  row_id bigint generated always as identity primary key,
  "po_number" text,
  "company_code" text,
  "po_type" text,
  "vendor_id" text,
  "vendor_name" text,
  "purchasing_org" text,
  "buyer_group" text,
  "po_date" text,
  "currency" text,
  "po_net_value" text,
  "payment_terms" text,
  "line_count" text
);
comment on table public."po_header" is 'One purchase order: who it was placed with, by which group company, when, and its total net value.';

drop table if exists public."po_line";
create table public."po_line" (
  row_id bigint generated always as identity primary key,
  "po_number" text,
  "po_item" text,
  "material_id" text,
  "item_text" text,
  "material_group" text,
  "plant_code" text,
  "account_assignment" text,
  "item_category" text,
  "ordered_qty" text,
  "order_unit" text,
  "net_price" text,
  "price_unit" text,
  "line_net_value" text,
  "over_delivery_tolerance_pct" text,
  "delivery_completed_flag" text,
  "final_invoice_flag" text,
  "deletion_flag" text,
  "line_status" text,
  "delivery_date" text,
  "buyer_note" text
);
comment on table public."po_line" is 'One line of a purchase order: what was ordered, how much, in which unit, at what price, and whether the line is still open.';

drop table if exists public."material";
create table public."material" (
  row_id bigint generated always as identity primary key,
  "material_id" text,
  "description" text,
  "material_type" text,
  "material_group" text,
  "material_group_text" text,
  "base_unit" text,
  "usual_order_unit" text,
  "category" text,
  "hsn_sac_code" text,
  "gst_rate_pct" text
);
comment on table public."material" is 'One material or service the group buys, with its policy category, base unit and GST code.';

drop table if exists public."unit_conversion";
create table public."unit_conversion" (
  row_id bigint generated always as identity primary key,
  "material_id" text,
  "description" text,
  "alternative_unit" text,
  "base_units" text,
  "alternative_units" text,
  "base_unit" text,
  "reads_as" text
);
comment on table public."unit_conversion" is 'One unit conversion for one material, for example 1 BAG of this cement = 50 KG.';

drop table if exists public."goods_receipt";
create table public."goods_receipt" (
  row_id bigint generated always as identity primary key,
  "receipt_doc_number" text,
  "receipt_doc_year" text,
  "receipt_doc_line" text,
  "movement_type" text,
  "posting_date" text,
  "po_number" text,
  "po_item" text,
  "material_id" text,
  "plant_code" text,
  "vendor_id" text,
  "qty_entered" text,
  "qty_unit_entered" text,
  "original_receipt_doc" text,
  "original_receipt_line" text,
  "delivery_note_ref" text,
  "weighbridge_slip" text,
  "vehicle_number" text,
  "remark" text
);
comment on table public."goods_receipt" is 'One receipt of goods or services at a site against a PO line, or a reversal or return of an earlier receipt.';

drop table if exists public."invoice_header";
create table public."invoice_header" (
  row_id bigint generated always as identity primary key,
  "invoice_doc_number" text,
  "fiscal_year" text,
  "company_code" text,
  "vendor_id" text,
  "vendor_name" text,
  "vendor_gstin" text,
  "vendor_invoice_number" text,
  "invoice_date" text,
  "posting_date" text,
  "parked_at" text,
  "parked_by" text,
  "po_numbers_quoted" text,
  "currency" text,
  "gross_amount" text,
  "gst_amount" text,
  "status" text,
  "invoice_pdf_path" text
);
comment on table public."invoice_header" is 'One parked vendor invoice waiting for the match: the trigger.';

drop table if exists public."invoice_line";
create table public."invoice_line" (
  row_id bigint generated always as identity primary key,
  "invoice_doc_number" text,
  "invoice_line_number" text,
  "po_number" text,
  "po_item_quoted" text,
  "material_id" text,
  "item_text" text,
  "hsn_sac_code" text,
  "billed_qty" text,
  "billed_unit" text,
  "unit_price" text,
  "line_net_amount" text,
  "gst_rate_pct" text,
  "gst_amount" text
);
comment on table public."invoice_line" is 'One line of a parked vendor invoice, as the vendor billed it.';

drop table if exists public."prior_invoice";
create table public."prior_invoice" (
  row_id bigint generated always as identity primary key,
  "invoice_doc_number" text,
  "fiscal_year" text,
  "invoice_line_number" text,
  "vendor_id" text,
  "vendor_invoice_number" text,
  "invoice_date" text,
  "posting_date" text,
  "po_number" text,
  "po_item" text,
  "material_id" text,
  "invoiced_qty" text,
  "order_unit" text,
  "unit_price" text,
  "net_amount" text,
  "final_invoice_flag" text,
  "status" text,
  "reversal_date" text
);
comment on table public."prior_invoice" is 'One earlier invoice line already posted (or posted and reversed) against a PO line in this pack.';

drop table if exists public."vendor";
create table public."vendor" (
  row_id bigint generated always as identity primary key,
  "vendor_id" text,
  "legal_name" text,
  "supplies" text,
  "street" text,
  "city" text,
  "state" text,
  "gst_state_code" text,
  "pin_code" text,
  "pan" text,
  "gstin" text,
  "is_msme" text,
  "udyam_number" text,
  "contact_name" text,
  "contact_email" text,
  "accounts_email" text,
  "phone" text,
  "payment_terms" text
);
comment on table public."vendor" is 'One vendor, with address, tax ids, MSME status and contacts.';
